import UIKit

class StackedDrawables: UIView {

    private var layers: [UIImageView] = []
    private var iconScale: CGFloat = 0.70
    private var shouldPlaceIcons = true

    init(layers: [UIImageView], iconScale: CGFloat = 0.70) {
        self.layers = layers
        self.iconScale = iconScale
        super.init(frame: .zero) // Important: Initialize the frame
        setupViews()
    }

    required init?(coder: NSCoder) {
        self.layers = []
        self.iconScale = 0.70
        super.init(coder: coder)
        setupViews()
    }

    private func setupViews() {
        for layer in layers {
            addSubview(layer)
            layer.contentMode = .scaleAspectFit // Or .scaleToFill, depending on desired behavior
        }
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        if shouldPlaceIcons {
            placeIcons()
            shouldPlaceIcons = false
        }
    }

    private func placeIcons() {
        shouldPlaceIcons = false

        let newWidth = bounds.width
        let iconsSize = floor(newWidth * iconScale).rounded()
        let iconsInset = (newWidth - iconsSize) - 1

        for (index, layer) in layers.enumerated() {
            layer.frame = CGRect(x: 0, y: 0, width: iconsSize, height: iconsSize)
            layer.center = CGPoint(x: bounds.midX, y: bounds.midY)

            switch index {
            case 1:
                layer.frame.origin.x = iconsInset
            case 0:
                layer.frame.origin.y = iconsInset
            default:
                break
            }
        }
        setNeedsDisplay() // Trigger redraw
    }
}

