export default function() {
  let csvData = '';

  self.onmessage = function(event) {
    const { url, delimiter } = event.data;

    fetch(url)
      .then(response => response.text())
      .then(data => {
        csvData = data;
        self.postMessage({ type: 'data', data: csvData });
      })
      .catch(error => {
        self.postMessage({ type: 'error', error: error.message });
      });
  };

  self.onmessageerror = function(error) {
    self.postMessage({ type: 'error', error: 'Message error: ' + error.message });
  };
}
```

**Explanation:**

*   **`self.onmessage`:** This is the event handler that listens for messages sent from the main thread (your Ember component).  The `event.data` object contains the data sent from the main thread.
